const email = `test${Date.now()}@mail.com`;
const password = 'Password1';
// Слідкуємо за ключовими запитами бекенду
cy.intercept('POST', '/api/cars').as('createCar');
cy.intercept('POST', '/api/auth/signin').as('loginUser');
cy.visit('/');
cy.contains('Sign up').click();
_RegistrationPage.default.typeName('John');
_RegistrationPage.default.typeLastName('Doe');
_RegistrationPage.default.typeEmail(email);
_RegistrationPage.default.typePassword(password);
_RegistrationPage.default.typeRepeatPassword(password);
_RegistrationPage.default.clickRegister();
cy.contains('Garage', {
  timeout: 15000
});
// Створюємо машину одразу після реєстрації
_GaragePage.default.addCar('BMW', 'X5', '10000');
// Чекаємо, поки бекенд реально створить авто в базі даних
cy.wait('@createCar', {
  timeout: 15000
});
cy.get('.car-item', {
  timeout: 10000
}).should('be.visible');
// Робимо Logout
cy.get('.user-nav_toggle').click({
  force: true
});
cy.contains('Logout').click({
  force: true
});
// Логінимося назад
cy.contains('Sign In').click({
  force: true
});
cy.get('#signinEmail').type(email, {
  force: true
});
cy.get('#signinPassword').type(password, {
  sensitive: true,
  force: true
});
cy.contains('Login').click({
  force: true
});
// Чекаємо на успішну авторизацію бекендом
cy.wait('@loginUser', {
  timeout: 15000
});
cy.contains('Garage', {
  timeout: 15000
});
cy.get('.car-item', {
  timeout: 10000
}).should('be.visible');
